package project.init.account.service.impl;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import project.init.account.domain.entity.Role;import project.init.account.repository.RoleRepository;import project.init.account.service.RoleService;import java.util.List;@Service@RequiredArgsConstructorpublic class RoleServiceImpl implements RoleService {    private final RoleRepository roleRepository;    @Override    public List<Role> findByCodeIn(List<String> roles) {        return roleRepository.findByCodeIn(roles);    }}